import openpyxl
wb = openpyxl.load_workbook('Cost Estimates/DSR_Ph3_Engineers_Estimate.xlsx')
ws = wb['Estimate']

# Print all rows with values to find the total
print("All rows with values in Estimate sheet:")
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, values_only=False):
    row_vals = []
    for cell in row:
        if cell.value is not None:
            row_vals.append(f"{cell.coordinate}: {cell.value}")
    if row_vals:
        print(f"Row {row[0].row}: {' | '.join(row_vals[:5])}")  # limit to 5 for brevity

# Check the total row
print("\n=== Checking total rows ===")
# Row 193 should be the total
for row in [188, 189, 190, 191, 192, 193]:
    vals = []
    for cell in ws[row]:
        if cell.value is not None:
            vals.append(f"{cell.coordinate}: {cell.value}")
    if vals:
        print(f"Row {row}: {' | '.join(vals)}")
EOF
